package com.collectiq.web;
import com.collectiq.security.TenantContext;import org.springframework.web.bind.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.client.RestClient;import java.util.*;
@RestController @RequestMapping("/api/whatsapp") public class WhatsAppController{
 private final JdbcTemplate db;private final RestClient http=RestClient.create();@Value("${WHATSAPP_TOKEN:}")String token;@Value("${WHATSAPP_PHONE_NUMBER_ID:}")String phoneId;@Value("${WHATSAPP_API_VERSION:v21.0}")String version;
 public WhatsAppController(JdbcTemplate d){db=d;}
 @GetMapping("/status")public Map<String,Object> status(){return Map.of("configured",!token.isBlank()&&!phoneId.isBlank(),"mode","Cloud API; approval required");}
 @PostMapping("/send-approved")public Map<String,Object> send(@RequestBody Map<String,Long>b){if(token.isBlank()||phoneId.isBlank())throw new IllegalStateException("WhatsApp Cloud API credentials not configured");Long id=b.get("approvalId");if(id==null)throw new IllegalArgumentException("approvalId required");Map<String,Object>a=db.queryForMap("select recipient,message from reminder_approvals where id=? and tenant_id=? and status='APPROVED' and sent_at is null",id,TenantContext.get());String to=Objects.toString(a.get("recipient"),"");String message=Objects.toString(a.get("message"),"");if(to.isBlank()||message.isBlank())throw new IllegalArgumentException("Approved reminder has no recipient/message");Map<String,Object> payload=Map.of("messaging_product","whatsapp","recipient_type","individual","to",to,"type","text","text",Map.of("preview_url",false,"body",message));Map response=http.post().uri("https://graph.facebook.com/"+version+"/"+phoneId+"/messages").header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).body(payload).retrieve().body(Map.class);db.update("update reminder_approvals set sent_at=now(),status='SENT' where id=? and tenant_id=? and status='APPROVED' and sent_at is null",id,TenantContext.get());db.update("insert into audit_events(tenant_id,event_type,entity_id,detail) values(?,'WHATSAPP_SENT',?,?::jsonb)",TenantContext.get(),id,"{}");return Map.of("sent",true,"providerResponse",response);}
}